function v93Esc(v){return String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function reviewCardForEdge(e){
  const rows=REVIEW_BY_EDGE[e?.id]||[]; if(!rows.length)return '';
  const labels=[...new Set(rows.map(x=>x.label).filter(Boolean))];
  const statuses=[...new Set(rows.map(x=>x.baseline_status).filter(Boolean))];
  const issues=[...new Set(rows.flatMap(x=>x.issues||[]))];
  const hasWarn=rows.some(x=>x.scope_conflict)||issues.some(x=>x!=='PAIR_CANDIDATE_NOT_DOCUMENT_IDENTITY')||statuses.includes('SOURCE_GAP');
  const chips=labels.map(x=>`<span class="review-chip ${/конфликт|не подтверждена|не установлено/i.test(x)?'warn':''}">${v93Esc(x)}</span>`).join('');
  const issueHtml=issues.length?`<ul class="review-list">${issues.map(x=>`<li>${v93Esc(REVIEW_ISSUE_LABELS[x]||x)}</li>`).join('')}</ul>`:'';
  const ids=rows.map(x=>x.interaction_id).filter(Boolean);
  return `<div class="card review-card ${hasWarn?'warn':''}"><h4>Исследовательская проверка v92</h4><p><strong>Записей аудита:</strong> ${rows.length}${ids.length?` · <span class="small">${v93Esc(ids.slice(0,6).join(', '))}${ids.length>6?' …':''}</span>`:''}</p><div>${chips}</div>${issueHtml}<p class="small">Аннотации не создают новое ребро и не меняют направление master-графа автоматически.</p></div>`;
}
