const filtersToggle=document.getElementById('filtersToggle');
const detailToggle=document.getElementById('detailToggle');
const filtersClose=document.getElementById('filtersClose');
const detailClose=document.getElementById('detailClose');
const uiBackdrop=document.getElementById('uiBackdrop');
const activeFilterCount=document.getElementById('activeFilterCount');
const selectionDot=document.getElementById('selectionDot');
function isCompactUI(){return window.matchMedia('(max-width:1100px)').matches}
function closePanels(){document.body.classList.remove('filters-open','detail-open','channel-filter-open');filtersToggle?.setAttribute('aria-expanded','false');detailToggle?.setAttribute('aria-expanded','false')}
function openFilters(){document.body.classList.remove('filters-open','detail-open');document.body.classList.add('channel-filter-open');filtersToggle?.setAttribute('aria-expanded','true');detailToggle?.setAttribute('aria-expanded','false')}
function openDetails(){if(!isCompactUI())return;document.body.classList.remove('filters-open','channel-filter-open');document.body.classList.add('detail-open');filtersToggle?.setAttribute('aria-expanded','false');detailToggle?.setAttribute('aria-expanded','true')}
filtersToggle?.addEventListener('click',()=>document.body.classList.contains('channel-filter-open')?closePanels():openFilters());
detailToggle?.addEventListener('click',()=>document.body.classList.contains('detail-open')?closePanels():openDetails());
filtersClose?.addEventListener('click',closePanels);detailClose?.addEventListener('click',closePanels);uiBackdrop?.addEventListener('click',closePanels);
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closePanels()});
document.addEventListener('pointerdown',ev=>{
  if(!document.body.classList.contains('channel-filter-open'))return;
  const panel=document.getElementById('channelToolbar134');
  const secondaryButton=document.getElementById('atlasFiltersButton');
  if(panel?.contains(ev.target)||filtersToggle?.contains(ev.target)||secondaryButton?.contains(ev.target))return;
  document.body.classList.remove('channel-filter-open');
  filtersToggle?.setAttribute('aria-expanded','false');
});

function hasDetailSelection(){
  const t=(detail?.textContent||'').trim();
  return !!t && !t.includes('Кликните по узлу или связи') && !t.includes('Здесь появится подробная карточка') && !t.includes('Здесь появится детальная карточка');
}
function syncDetailState(autoOpen=false){const has=hasDetailSelection();if(selectionDot)selectionDot.hidden=!has;if(autoOpen&&has&&isCompactUI())openDetails()}
const detailObserver=new MutationObserver(()=>syncDetailState(true));if(detail)detailObserver.observe(detail,{childList:true,subtree:true,characterData:true});syncDetailState(false);

function countActiveFilters(){
  let n=0;
  const rel=document.getElementById('relFilter'),mat=document.getElementById('matrixFilter'),dir=document.getElementById('directionFilter'),search=document.getElementById('search');
  if(rel&&rel.value!=='ALL')n++; if(mat&&mat.value!=='ALL')n++; if(dir&&dir.value!=='ALL')n++;
  for(const id of ['onlySourced','onlyCore','onlyCommon'])if(document.getElementById(id)?.checked)n++;
  if(search?.value.trim())n++; if(typeof focusSet!=='undefined'&&focusSet.size)n++;
  if(typeof channelFocusId!=='undefined'&&channelFocusId)n++; if(typeof structureMinistryFocusId!=='undefined'&&structureMinistryFocusId)n++;
  return n;
}
function updateActiveFilterCount(){const n=countActiveFilters();if(!activeFilterCount)return;activeFilterCount.hidden=n===0;activeFilterCount.textContent=String(n)}
for(const id of ['relFilter','matrixFilter','directionFilter','onlySourced','onlyCore','onlyCommon','search','channelFocusSelect','structureMinistrySelect']){
  const el=document.getElementById(id);if(el){el.addEventListener('change',updateActiveFilterCount);el.addEventListener('input',updateActiveFilterCount)}
}
document.getElementById('focusGrid')?.addEventListener('click',()=>setTimeout(updateActiveFilterCount,0));
