updateActiveFilterCount();

// More natural desktop trackpad/mouse zoom. Zoom around pointer position.
if(typeof svg!=='undefined'){
  svg.addEventListener('wheel',ev=>{
    ev.preventDefault();
    const rect=svg.getBoundingClientRect();const px=ev.clientX-rect.left,py=ev.clientY-rect.top;
    const old=scale;const factor=Math.exp(-ev.deltaY*0.0012);const next=Math.max(.36,Math.min(3.2,old*factor));
    if(Math.abs(next-old)<.0001)return;
    tx=px-(px-tx)*(next/old);ty=py-(py-ty)*(next/old);scale=next;applyTransform();
  },{passive:false});

  // One-finger background pan + two-finger pinch for touch devices.
  let touches=new Map(),lastPinch=null,panMoved=false;
  function touchPoint(ev){const r=svg.getBoundingClientRect();return {x:ev.clientX-r.left,y:ev.clientY-r.top}}
  svg.addEventListener('pointerdown',ev=>{
    if(ev.pointerType!=='touch')return;
    touches.set(ev.pointerId,touchPoint(ev));try{svg.setPointerCapture(ev.pointerId)}catch(_){ }
    if(touches.size===2){const p=[...touches.values()];lastPinch={dist:Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y),cx:(p[0].x+p[1].x)/2,cy:(p[0].y+p[1].y)/2};}
    panMoved=false;
  });
  svg.addEventListener('pointermove',ev=>{
    if(ev.pointerType!=='touch'||!touches.has(ev.pointerId))return;
    const prev=touches.get(ev.pointerId),now=touchPoint(ev);touches.set(ev.pointerId,now);
    if(touches.size===1 && (ev.target===svg || ev.target?.closest?.('#graph'))){const dx=now.x-prev.x,dy=now.y-prev.y;if(Math.abs(dx)+Math.abs(dy)>1){tx+=dx;ty+=dy;applyTransform();panMoved=true;}}
    else if(touches.size>=2){const p=[...touches.values()].slice(0,2);const dist=Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y),cx=(p[0].x+p[1].x)/2,cy=(p[0].y+p[1].y)/2;if(lastPinch&&lastPinch.dist>0){const old=scale,next=Math.max(.36,Math.min(3.2,old*(dist/lastPinch.dist)));tx=cx-(cx-tx)*(next/old)+(cx-lastPinch.cx);ty=cy-(cy-ty)*(next/old)+(cy-lastPinch.cy);scale=next;applyTransform();panMoved=true;}lastPinch={dist,cx,cy};}
  });
  const endTouch=ev=>{touches.delete(ev.pointerId);if(touches.size<2)lastPinch=null};
  svg.addEventListener('pointerup',endTouch);svg.addEventListener('pointercancel',endTouch);
}

document.body.dataset.uiMode=(typeof graphMode!=='undefined'?graphMode:'OVERVIEW');
try{
